(7254000, 1127583, 118154, '<td valign="top">A little much on the forehead but such wonderful eyes your model has.</td>', 'A little much on the forehead but such wonderful eyes your model has.', '2014-08-23 04:11:31.000000', NULL, 1),
(7254033, 1127609, 149964, '<td valign="top">I love the subject and you''e really captured the purple.  I''m not sure about the focus though; my eye is wandering a little trying to catch it.</td>', 'I love the subject and you''e really captured the purple.  I''m not sure about the focus though; my eye is wandering a little trying to catch it.', '2014-08-23 08:59:49.000000', NULL, 1),
(7254035, 1127561, 149964, '<td valign="top">Beautiful subject  and the colours are gorgeous, especially the contrast with the background.. I wasn''t sure about the focus though - personally I''d have liked it a little sharper</td>', 'Beautiful subject  and the colours are gorgeous, especially the contrast with the background.. I wasn''t sure about the focus though - personally I''d have liked it a little sharper', '2014-08-23 09:02:15.000000', NULL, 1),
(7254036, 1127685, 149964, '<td valign="top">Really like the take on this - good to have something other than flowers!  I like the way the gloved hand stands out but I think it may have looked better with greater contrast. I though the overall picture was a little too dark.</td>', 'Really like the take on this - good to have something other than flowers!  I like the way the gloved hand stands out but I think it may have looked better with greater contrast. I though the overall picture was a little too dark.', '2014-08-23 09:04:43.000000', NULL, 1),
(7254037, 1127410, 149964, '<td valign="top">Beautiful colours and I like both the composition and the contrasting background. Personally, I wasn''t so fond of the soft focus - I think the petals could have been even more striking if sharpened up.</td>', 'Beautiful colours and I like both the composition and the contrasting background. Personally, I wasn''t so fond of the soft focus - I think the petals could have been even more striking if sharpened up.', '2014-08-23 09:06:48.000000', NULL, 1),
(7254038, 1127734, 149964, '<td valign="top">I love the composition and texture-like effects on this. And now I''m probably just being pedantic.....but I''d like it to have come across with more purple.</td>', 'I love the composition and texture-like effects on this. And now I''m probably just being pedantic.....but I''d like it to have come across with more purple.', '2014-08-23 09:11:10.000000', NULL, 1),
(7254039, 1127390, 149964, '<td valign="top">Really like this calm scene. Personally I think I''d have preferred it if some of the foreground had been cropped out and the image centred to highlight the symmetry.</td>', 'Really like this calm scene. Personally I think I''d have preferred it if some of the foreground had been cropped out and the image centred to highlight the symmetry.', '2014-08-23 09:19:50.000000', NULL, 1),
(7254176, 1127462, 124982, '<td valign="top">Very interesting and edgy composition! Definitely like the whole shabang except for the dirty hands and arms.<br/> <br/>I suspect you''re probably getting dinged from some for the "unladylike" pose though/</td>', 'Very interesting and edgy composition! Definitely like the whole shabang except for the dirty hands and arms. I suspect you''re probably getting dinged from some for the "unladylike" pose though/', '2014-08-23 16:55:52.000000', NULL, 1),
(7254177, 1127690, 124982, '<td valign="top">Lovely composition and lighting. Purple is too saturated for my liking though -- too unnatural.</td>', 'Lovely composition and lighting. Purple is too saturated for my liking though -- too unnatural.', '2014-08-23 16:57:07.000000', NULL, 1),
(7254179, 1127731, 124982, '<td valign="top">I like the shot, but think a more subtle processing with the purple would''ve been so much nicer!</td>', 'I like the shot, but think a more subtle processing with the purple would''ve been so much nicer!', '2014-08-23 16:58:40.000000', NULL, 1),
